sqlMap.insert:
/*ReportComm.insertDefaultNewInfo*/ INSERT INTO tb_reportinfo ( report_cd, report_detl_cd, fis_year, bgt_dgr, report_nm, sheet_nm, print_paper_size, print_scale, right_margin, left_margin, top_margin, bottom_margin, header_margin, footer_margin, zoom, regi_id, regi_date, modi_id, modi_date ) SELECT report_cd, report_detl_cd, #fisYear# as fis_year, #bgtDgr# AS bgt_dgr, REPLACE(REPORT_NM, '1', (SELECT B.ADD_TIMES FROM TB_BGTDGR B WHERE B.fis_year = #fisYear# AND B.BGT_DGR = #bgtDgr#)) AS REPORT_NM, sheet_nm, print_paper_size, print_scale, right_margin, left_margin, top_margin, bottom_margin, header_margin, footer_margin, zoom, regi_id, SYSTIMESTAMP, modi_id, SYSTIMESTAMP FROM tb_reportinfo WHERE 1 = 1 AND REPORT_CD = #reportCd# AND REPORT_DETL_CD = #reportDetlCd# AND FIS_YEAR = '2019'
BGT_DGR = '1'
BGT_DGR = '3'
